CREATE TABLE [DBO].[PRICE_LIST_ITEM_T]
(
 [PRICE_LIST_ITEM_ID] int IDENTITY (1, 1) NOT NULL ,
 [PRICE_LIST_ID]      int NOT NULL ,
 [ITEM_TYPE]          nvarchar(20) NOT NULL ,
 [PRODUCT_ID]         int NULL ,
 [SERVICE_ID]         int NULL ,
 [OFFERING_ID]        int NULL ,
 [BUNDLE_ID]          int NULL ,
 [UNIT_PRICE]         decimal(18,4) NOT NULL ,
 [MIN_QUANTITY]       decimal(18,4) NOT NULL CONSTRAINT [DF_PriceListItem_MinQty] DEFAULT (1) ,
 [MAX_QUANTITY]       decimal(18,4) NULL ,

 CONSTRAINT [PK_PRICE_LIST_ITEM] PRIMARY KEY NONCLUSTERED ([PRICE_LIST_ITEM_ID] ASC),
 CONSTRAINT [UQ_PRICE_LIST_ITEM_UNIQUE] UNIQUE NONCLUSTERED ([PRICE_LIST_ID] ASC, [ITEM_TYPE] ASC, [PRODUCT_ID] ASC, [SERVICE_ID] ASC, [OFFERING_ID] ASC, [BUNDLE_ID] ASC, [MIN_QUANTITY] ASC),
 CONSTRAINT [FK_PRICE_LIST_ITEM_BUNDLE] FOREIGN KEY ([BUNDLE_ID])  REFERENCES [DBO].[BUNDLE_T]([BUNDLE_ID]),
 CONSTRAINT [FK_PRICE_LIST_ITEM_OFFERING] FOREIGN KEY ([OFFERING_ID])  REFERENCES [DBO].[OFFERING_T]([OFFERING_ID]),
 CONSTRAINT [FK_PRICE_LIST_ITEM_PRICE_LIST] FOREIGN KEY ([PRICE_LIST_ID])  REFERENCES [DBO].[PRICE_LIST_T]([PRICE_LIST_ID]),
 CONSTRAINT [FK_PRICE_LIST_ITEM_PRODUCT] FOREIGN KEY ([PRODUCT_ID])  REFERENCES [DBO].[PRODUCT_T]([PRODUCT_ID]),
 CONSTRAINT [FK_PRICE_LIST_ITEM_SERVICE] FOREIGN KEY ([SERVICE_ID])  REFERENCES [DBO].[SERVICE_T]([SERVICE_ID]),
 CONSTRAINT [CK_PRICE_LIST_ITEM_TYPE] CHECK ( (ItemType = N'Product' AND ProductId IS NOT NULL AND ServiceId IS NULL AND OfferingId IS NULL AND BundleId IS NULL)
    OR (ItemType = N'Service' AND ServiceId IS NOT NULL AND ProductId IS NULL AND OfferingId IS NULL AND BundleId IS NULL)
    OR (ItemType = N'Offering' AND OfferingId IS NOT NULL AND ProductId IS NULL AND ServiceId IS NULL AND BundleId IS NULL)
    OR (ItemType = N'Bundle' AND BundleId IS NOT NULL AND ProductId IS NULL AND ServiceId IS NULL AND OfferingId IS NULL) ),
 CONSTRAINT [CK_PRICE_LIST_ITEM_QTY_RANGE] CHECK ( MaxQuantity IS NULL OR MaxQuantity >= MinQuantity )
);
GO

