 [ITEM_TYPE]       nvarchar(20) NOT NULL ,
 [QUANTITY]        decimal(18,4) NOT NULL CONSTRAINT [DF_BundleItem_Qty] DEFAULT (1) ,
 [SORT_ORDER]      int NOT NULL CONSTRAINT [DF_BundleItem_Sort] DEFAULT (1) ,
 [IS_OPTIONAL]     bit NOT NULL CONSTRAINT [DF_BundleItem_IsOptional] DEFAULT (0) ,

 CONSTRAINT [PK_BUNDLE_ITEM] PRIMARY KEY NONCLUSTERED ([BUNDLE_ITEM_ID] ASC),
 CONSTRAINT [UQ_BUNDLE_ITEM_UNIQUE_LINE] UNIQUE NONCLUSTERED ([BUNDLE_ID] ASC, [ITEM_TYPE] ASC, [OFFERING_ID] ASC, [CHILD_BUNDLE_ID] ASC),
