 CONSTRAINT [CK_BUNDLE_ITEM_TYPE] CHECK ( (ItemType = N'Offering' AND OfferingId IS NOT NULL AND ChildBundleId IS NULL)
    OR
    (ItemType = N'Bundle' AND ChildBundleId IS NOT NULL AND OfferingId IS NULL AND ChildBundleId <> BundleId) )
);
