CREATE TABLE [DBO].[SALES_ORDER_LINE_T]
(
 [SALES_ORDER_LINE_ID] int IDENTITY (1, 1) NOT NULL ,
 [SALES_ORDER_ID]      int NOT NULL ,
 [LINE_NUMBER]         int NOT NULL ,
 [LINE_TYPE]           nvarchar(20) NOT NULL ,
 [OFFERING_ID]         int NULL ,
 [BUNDLE_ID]           int NULL ,
 [QUANTITY]            decimal(18,4) NOT NULL ,
 [UNIT_PRICE]          decimal(18,4) NOT NULL ,
 [DISCOUNT_PCT]        decimal(9,4) NOT NULL CONSTRAINT [DF_SalesOrderLine_Discount] DEFAULT (0) ,
 [TAX_PCT]             decimal(9,4) NOT NULL CONSTRAINT [DF_SalesOrderLine_Tax] DEFAULT (0) ,
 [START_DATE]          date NULL ,
 [END_DATE]            date NULL ,
 [CREATED_AT]          datetime2(3) NOT NULL CONSTRAINT [DF_SalesOrderLine_CreatedAt] DEFAULT (SYSUTCDATETIME()) ,

 CONSTRAINT [PK_SALES_ORDER_LINE] PRIMARY KEY NONCLUSTERED ([SALES_ORDER_LINE_ID] ASC),
 CONSTRAINT [UQ_SALES_ORDER_LINE] UNIQUE NONCLUSTERED ([SALES_ORDER_ID] ASC, [LINE_NUMBER] ASC),
 CONSTRAINT [FK_SALES_ORDER_LINE_BUNDLE] FOREIGN KEY ([BUNDLE_ID])  REFERENCES [DBO].[BUNDLE_T]([BUNDLE_ID]),
 CONSTRAINT [FK_SALES_ORDER_LINE_OFFERING] FOREIGN KEY ([OFFERING_ID])  REFERENCES [DBO].[OFFERING_T]([OFFERING_ID]),
 CONSTRAINT [FK_SALES_ORDER_LINE_ORDER] FOREIGN KEY ([SALES_ORDER_ID])  REFERENCES [DBO].[SALES_ORDER_T]([SALES_ORDER_ID]),
 CONSTRAINT [CK_SALES_ORDER_LINE_TYPE] CHECK ( (LineType = N'Offering' AND OfferingId IS NOT NULL AND BundleId IS NULL)
    OR
    (LineType = N'Bundle' AND BundleId IS NOT NULL AND OfferingId IS NULL) ),
 CONSTRAINT [CK_SALES_ORDER_LINE_DISCOUNT] CHECK ( DiscountPct >= 0 AND DiscountPct <= 100 ),
 CONSTRAINT [CK_SALES_ORDER_LINE_DATES] CHECK ( EndDate IS NULL OR StartDate IS NULL OR EndDate >= StartDate )
);
GO

