ALTER VIEW CONSUMPTION.[vw_ComponentUsage] AS
SELECT 
    'Offering' AS ParentType,
    o.OfferingId AS ParentId,
    o.OfferingCode AS ParentCode,
    o.OfferingName AS ParentName,
    oi.ItemType,
    CASE 
        WHEN oi.ProductId IS NOT NULL THEN 'Product'
        WHEN oi.ServiceId IS NOT NULL THEN 'Service'
        ELSE 'Unknown'
    END AS ComponentType,
    CASE 
        WHEN oi.ProductId IS NOT NULL THEN (SELECT SKU FROM dbo.Product WHERE ProductId = oi.ProductId)
        WHEN oi.ServiceId IS NOT NULL THEN (SELECT ServiceCode FROM dbo.Service WHERE ServiceId = oi.ServiceId)
        ELSE NULL
    END AS ComponentCode,
    CASE 
        WHEN oi.ProductId IS NOT NULL THEN (SELECT ProductName FROM dbo.Product WHERE ProductId = oi.ProductId)
        WHEN oi.ServiceId IS NOT NULL THEN (SELECT ServiceName FROM dbo.Service WHERE ServiceId = oi.ServiceId)
        ELSE NULL
    END AS ComponentName,
    oi.Quantity,
    oi.SortOrder,
    oi.IsOptional
FROM dbo.OfferingItem oi
INNER JOIN dbo.Offering o ON oi.OfferingId = o.OfferingId

UNION ALL

SELECT 
    'Bundle' AS ParentType,
    b.BundleId AS ParentId,
    b.BundleCode AS ParentCode,
    b.BundleName AS ParentName,
    bi.ItemType,
    CASE 
        WHEN bi.OfferingId IS NOT NULL THEN 'Offering'
        WHEN bi.ChildBundleId IS NOT NULL THEN 'Bundle'
        ELSE 'Unknown'
    END AS ComponentType,
    CASE 
        WHEN bi.OfferingId IS NOT NULL THEN (SELECT OfferingCode FROM dbo.Offering WHERE OfferingId = bi.OfferingId)
        WHEN bi.ChildBundleId IS NOT NULL THEN (SELECT BundleCode FROM dbo.Bundle WHERE BundleId = bi.ChildBundleId)
        ELSE NULL
    END AS ComponentCode,
    CASE 
        WHEN bi.OfferingId IS NOT NULL THEN (SELECT OfferingName FROM dbo.Offering WHERE OfferingId = bi.OfferingId)
        WHEN bi.ChildBundleId IS NOT NULL THEN (SELECT BundleName FROM dbo.Bundle WHERE BundleId = bi.ChildBundleId)
        ELSE NULL
    END AS ComponentName,
    bi.Quantity,
    bi.SortOrder,
    bi.IsOptional
FROM dbo.BundleItem bi
INNER JOIN dbo.Bundle b ON bi.BundleId = b.BundleId;
GO

ALTER VIEW CONSUMPTION.[vw_ContractAnalysis] AS
SELECT 
    cc.CustomerContractId,
    cc.CustomerId,
    c.CustomerName,
    cc.ContractNumber,
    cc.ContractName,
    cc.StartDate,
    cc.EndDate,
    CASE 
        WHEN cc.EndDate < CAST(GETDATE() AS DATE) THEN 'Expired'
        WHEN cc.EndDate >= CAST(GETDATE() AS DATE) THEN 'Active'
        ELSE 'Upcoming'
    END AS ContractStatus,
    DATEDIFF(DAY, cc.StartDate, ISNULL(cc.EndDate, CAST(GETDATE() AS DATE))) AS ContractDurationDays,
    cc.Status,
    cc.PriceListId,
    pl.PriceListCode,
    pl.PriceListName,
    COUNT(DISTINCT ci.ContractItemId) AS ItemCount,
    cc.CreatedAt
FROM dbo.CustomerContract cc
INNER JOIN dbo.Customer c ON cc.CustomerId = c.CustomerId
LEFT JOIN dbo.PriceList pl ON cc.PriceListId = pl.PriceListId
LEFT JOIN dbo.ContractItem ci ON cc.CustomerContractId = ci.CustomerContractId
GROUP BY 
    cc.CustomerContractId, cc.CustomerId, c.CustomerName, cc.ContractNumber,
    cc.ContractName, cc.StartDate, cc.EndDate, cc.Status, cc.PriceListId,
    pl.PriceListCode, pl.PriceListName, cc.CreatedAt;
GO

ALTER VIEW CONSUMPTION.[vw_CustomerLocationSummary] AS
SELECT 
    cl.CustomerLocationId,
    cl.CustomerId,
    c.CustomerName,
    cl.LocationCode,
    cl.LocationName,
    cl.AddressLine1,
    cl.AddressLine2,
    cl.City,
    cl.StateProvince,
    cl.PostalCode,
    cl.CountryCode,
    cl.IsPrimary,
    COUNT(DISTINCT so.SalesOrderId) AS OrdersFromLocation,
    COUNT(DISTINCT con.CustomerContactId) AS ContactsAtLocation,
    cl.CreatedAt
FROM dbo.CustomerLocation cl
INNER JOIN dbo.Customer c ON cl.CustomerId = c.CustomerId
LEFT JOIN dbo.SalesOrder so ON cl.CustomerLocationId = so.CustomerLocationId
LEFT JOIN dbo.CustomerContact con ON cl.CustomerId = con.CustomerId
GROUP BY 
    cl.CustomerLocationId, cl.CustomerId, c.CustomerName, cl.LocationCode,
    cl.LocationName, cl.AddressLine1, cl.AddressLine2, cl.City, cl.StateProvince,
    cl.PostalCode, cl.CountryCode, cl.IsPrimary, cl.CreatedAt;
GO

ALTER VIEW CONSUMPTION.[vw_CustomerRevenueAnalysis] AS
SELECT 
    c.CustomerId,
    c.CustomerNumber,
    c.CustomerName,
    c.CustomerStatus,
    YEAR(so.OrderDate) AS OrderYear,
    MONTH(so.OrderDate) AS OrderMonth,
    COUNT(DISTINCT so.SalesOrderId) AS OrderCount,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100)) AS GrossRevenue,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * (1 - 1 / (1 + sol.TaxPct / 100))) AS TotalDiscount,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * (sol.TaxPct / 100)) AS TotalTax,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * (1 + sol.TaxPct / 100)) AS NetRevenue
FROM dbo.Customer c
INNER JOIN dbo.SalesOrder so ON c.CustomerId = so.CustomerId
LEFT JOIN dbo.SalesOrderLine sol ON so.SalesOrderId = sol.SalesOrderId
WHERE so.Status IN ('Confirmed', 'Completed')
GROUP BY 
    c.CustomerId, c.CustomerNumber, c.CustomerName, c.CustomerStatus,
    YEAR(so.OrderDate), MONTH(so.OrderDate);
GO

ALTER VIEW CONSUMPTION.[vw_CustomerSummary] AS
SELECT 
    c.CustomerId,
    c.CustomerNumber,
    c.CustomerName,
    c.CustomerStatus,
    c.DefaultCurrencyCode,
    COUNT(DISTINCT so.SalesOrderId) AS TotalOrders,
    COUNT(DISTINCT cc.CustomerContractId) AS TotalContracts,
    COUNT(DISTINCT se.ServiceEntitlementId) AS TotalEntitlements,
    COUNT(DISTINCT cl.CustomerLocationId) AS TotalLocations,
    COUNT(DISTINCT con.CustomerContactId) AS TotalContacts,
    c.CreatedAt,
    c.UpdatedAt
FROM dbo.Customer c
LEFT JOIN dbo.SalesOrder so ON c.CustomerId = so.CustomerId
LEFT JOIN dbo.CustomerContract cc ON c.CustomerId = cc.CustomerId
LEFT JOIN dbo.ServiceEntitlement se ON c.CustomerId = se.CustomerId
LEFT JOIN dbo.CustomerLocation cl ON c.CustomerId = cl.CustomerId
LEFT JOIN dbo.CustomerContact con ON c.CustomerId = con.CustomerId
GROUP BY 
    c.CustomerId, c.CustomerNumber, c.CustomerName, c.CustomerStatus, 
    c.DefaultCurrencyCode, c.CreatedAt, c.UpdatedAt;
GO

ALTER VIEW CONSUMPTION.[vw_OfferingBundleAnalysis] AS
SELECT 
    'Offering' AS ItemType,
    o.OfferingId AS ItemId,
    o.OfferingCode AS ItemCode,
    o.OfferingName AS ItemName,
    o.OfferingDescription AS ItemDescription,
    ot.OfferingTypeName AS CategoryName,
    COUNT(DISTINCT oi.OfferingItemId) AS ComponentCount,
    o.IsActive,
    o.EffectiveFrom,
    o.EffectiveTo,
    o.CreatedAt,
    o.UpdatedAt
FROM dbo.Offering o
LEFT JOIN dbo.OfferingType ot ON o.OfferingTypeId = ot.OfferingTypeId
LEFT JOIN dbo.OfferingItem oi ON o.OfferingId = oi.OfferingId
GROUP BY 
    o.OfferingId, o.OfferingCode, o.OfferingName, o.OfferingDescription,
    ot.OfferingTypeName, o.IsActive, o.EffectiveFrom, o.EffectiveTo,
    o.CreatedAt, o.UpdatedAt

UNION ALL

SELECT 
    'Bundle' AS ItemType,
    b.BundleId AS ItemId,
    b.BundleCode AS ItemCode,
    b.BundleName AS ItemName,
    b.BundleDescription AS ItemDescription,
    'Bundle' AS CategoryName,
    COUNT(DISTINCT bi.BundleItemId) AS ComponentCount,
    b.IsActive,
    b.EffectiveFrom,
    b.EffectiveTo,
    b.CreatedAt,
    b.UpdatedAt
FROM dbo.Bundle b
LEFT JOIN dbo.BundleItem bi ON b.BundleId = bi.BundleId
GROUP BY 
    b.BundleId, b.BundleCode, b.BundleName, b.BundleDescription,
    b.IsActive, b.EffectiveFrom, b.EffectiveTo, b.CreatedAt, b.UpdatedAt;
GO

ALTER VIEW CONSUMPTION.[vw_PricingAnalysis] AS
SELECT 
    pl.PriceListId,
    pl.PriceListCode,
    pl.PriceListName,
    pl.CurrencyCode,
    pl.IsActive,
    pl.EffectiveFrom,
    pl.EffectiveTo,
    CASE 
        WHEN pl.EffectiveTo < CAST(GETDATE() AS DATE) THEN 'Expired'
        WHEN pl.EffectiveFrom <= CAST(GETDATE() AS DATE) AND (pl.EffectiveTo IS NULL OR pl.EffectiveTo >= CAST(GETDATE() AS DATE)) THEN 'Active'
        ELSE 'Upcoming'
    END AS PriceListStatus,
    COUNT(DISTINCT pli.PriceListItemId) AS PriceItemCount,
    MIN(pli.UnitPrice) AS MinPrice,
    MAX(pli.UnitPrice) AS MaxPrice,
    AVG(pli.UnitPrice) AS AvgPrice
FROM dbo.PriceList pl
LEFT JOIN dbo.PriceListItem pli ON pl.PriceListId = pli.PriceListId
GROUP BY 
    pl.PriceListId, pl.PriceListCode, pl.PriceListName, pl.CurrencyCode,
    pl.IsActive, pl.EffectiveFrom, pl.EffectiveTo;
GO

ALTER VIEW CONSUMPTION.[vw_ProductServiceCatalog] AS
SELECT 
    'Product' AS CatalogItemType,
    p.ProductId AS ItemId,
    p.SKU AS ItemCode,
    p.ProductName AS ItemName,
    p.ProductDescription AS ItemDescription,
    pc.CategoryName,
    sup.SupplierName AS SourceName,
    p.UomCode,
    uom.UomName,
    tc.TaxCategoryName,
    tc.TaxRatePct,
    p.IsActive,
    p.CreatedAt,
    p.UpdatedAt
FROM dbo.Product p
LEFT JOIN dbo.ProductCategory pc ON p.ProductCategoryId = pc.ProductCategoryId
LEFT JOIN dbo.Supplier sup ON p.SupplierId = sup.SupplierId
LEFT JOIN dbo.UnitOfMeasure uom ON p.UomCode = uom.UomCode
LEFT JOIN dbo.TaxCategory tc ON p.TaxCategoryId = tc.TaxCategoryId

UNION ALL

SELECT 
    'Service' AS CatalogItemType,
    s.ServiceId AS ItemId,
    s.ServiceCode AS ItemCode,
    s.ServiceName AS ItemName,
    s.ServiceDescription AS ItemDescription,
    sc.CategoryName,
    NULL AS SourceName,
    s.UomCode,
    uom.UomName,
    tc.TaxCategoryName,
    tc.TaxRatePct,
    s.IsActive,
    s.CreatedAt,
    s.UpdatedAt
FROM dbo.Service s
LEFT JOIN dbo.ServiceCategory sc ON s.ServiceCategoryId = sc.ServiceCategoryId
LEFT JOIN dbo.UnitOfMeasure uom ON s.UomCode = uom.UomCode
LEFT JOIN dbo.TaxCategory tc ON s.TaxCategoryId = tc.TaxCategoryId;
GO

ALTER VIEW CONSUMPTION.[vw_SalesOrderAnalysis] AS
SELECT 
    so.SalesOrderId,
    so.OrderNumber,
    so.CustomerId,
    c.CustomerName,
    so.OrderDate,
    so.CurrencyCode,
    so.Status,
    COUNT(DISTINCT sol.SalesOrderLineId) AS LineItemCount,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100)) AS GrossAmount,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * sol.TaxPct / 100) AS TotalTax,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * (1 + sol.TaxPct / 100)) AS NetAmount,
    so.CreatedAt,
    so.UpdatedAt
FROM dbo.SalesOrder so
INNER JOIN dbo.Customer c ON so.CustomerId = c.CustomerId
LEFT JOIN dbo.SalesOrderLine sol ON so.SalesOrderId = sol.SalesOrderId
GROUP BY 
    so.SalesOrderId, so.OrderNumber, so.CustomerId, c.CustomerName,
    so.OrderDate, so.CurrencyCode, so.Status, so.CreatedAt, so.UpdatedAt;
GO

ALTER VIEW CONSUMPTION.[vw_SalesOrderLineDetail] AS
SELECT 
    sol.SalesOrderLineId,
    sol.SalesOrderId,
    so.OrderNumber,
    sol.LineNumber,
    sol.LineType,
    CASE 
        WHEN sol.OfferingId IS NOT NULL THEN o.OfferingCode
        WHEN sol.BundleId IS NOT NULL THEN b.BundleCode
        ELSE NULL
    END AS ItemCode,
    CASE 
        WHEN sol.OfferingId IS NOT NULL THEN o.OfferingName
        WHEN sol.BundleId IS NOT NULL THEN b.BundleName
        ELSE NULL
    END AS ItemName,
    sol.Quantity,
    sol.UnitPrice,
    sol.DiscountPct,
    sol.TaxPct,
    sol.StartDate,
    sol.EndDate,
    DATEDIFF(DAY, ISNULL(sol.StartDate, so.OrderDate), ISNULL(sol.EndDate, GETDATE())) AS DurationDays,
    sol.Quantity * sol.UnitPrice AS LineGrossAmount,
    sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) AS LineDiscountedAmount,
    sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * (1 + sol.TaxPct / 100) AS LineNetAmount
FROM dbo.SalesOrderLine sol
INNER JOIN dbo.SalesOrder so ON sol.SalesOrderId = so.SalesOrderId
LEFT JOIN dbo.Offering o ON sol.OfferingId = o.OfferingId
LEFT JOIN dbo.Bundle b ON sol.BundleId = b.BundleId;
GO

ALTER VIEW CONSUMPTION.[vw_ServiceEntitlementAnalysis] AS
SELECT 
    se.ServiceEntitlementId,
    se.CustomerId,
    c.CustomerName,
    se.ServiceId,
    s.ServiceCode,
    s.ServiceName,
    se.SalesOrderLineId,
    so.OrderNumber,
    se.EntitlementStartDate,
    se.EntitlementEndDate,
    CASE 
        WHEN se.EntitlementEndDate IS NULL THEN 'Active'
        WHEN se.EntitlementEndDate < CAST(GETDATE() AS DATE) THEN 'Expired'
        ELSE 'Upcoming'
    END AS EntitlementStatus,
    DATEDIFF(DAY, se.EntitlementStartDate, ISNULL(se.EntitlementEndDate, CAST(GETDATE() AS DATE))) AS EntitlementDurationDays,
    se.Status,
    se.CreatedAt
FROM dbo.ServiceEntitlement se
INNER JOIN dbo.Customer c ON se.CustomerId = c.CustomerId
INNER JOIN dbo.Service s ON se.ServiceId = s.ServiceId
LEFT JOIN dbo.SalesOrderLine sol ON se.SalesOrderLineId = sol.SalesOrderLineId
LEFT JOIN dbo.SalesOrder so ON sol.SalesOrderId = so.SalesOrderId;
GO